<div class="rich-editor" data-rich-editor x-data="richEditor('{{ $editorKey }}')" @editor-value.window="if($event.detail.key==='{{ $editorKey }}')update($event.detail.html)"><div class="editor-toolbar">@foreach(['bold'=>'پررنگ','italic'=>'مورب','heading'=>'عنوان','bulletList'=>'فهرست','orderedList'=>'فهرست شماره‌دار','blockquote'=>'نقل قول','link'=>'لینک','unlink'=>'حذف لینک','table'=>'جدول','addRow'=>'ردیف +','addColumn'=>'ستون +','deleteRow'=>'حذف ردیف','deleteColumn'=>'حذف ستون','mergeCells'=>'ادغام','splitCell'=>'تفکیک','deleteTable'=>'حذف جدول','undo'=>'بازگشت','redo'=>'دوباره'] as $command=>$text)<button type="button" @mousedown.prevent @click="command('{{ $command }}')">{{ $text }}</button>@endforeach<button type="button" @mousedown.prevent @click="$refs.image.click()">تصویر</button><button type="button" @mousedown.prevent @click="$refs.gallery.click()">آلبوم تصاویر</button><button type="button" @mousedown.prevent @click="$refs.pdf.click()">PDF / پیوست</button><input type="file" x-ref="image" hidden accept="image/jpeg,image/png,image/webp" @change="upload($event,'image')"><input type="file" x-ref="gallery" hidden multiple accept="image/jpeg,image/png,image/webp" @change="upload($event,'gallery')"><input type="file" x-ref="pdf" hidden accept="application/pdf" @change="upload($event,'file')"></div><div x-ref="editor" class="prose-editor" aria-label="ویرایش متن"></div></div>